                    elif b.get('type')=='text':
                        blocks.append({'k':'text','len':len(b['text']),'text':b['text'][:6000]})
                    else: blocks.append({'k':b.get('type'),'len':len(json.dumps(b))})
            r['blocks']=blocks
            r['toolUseResult']=json.dumps(d.get('toolUseResult'))[:300] if d.get('toolUseResult') is not None else None
            r['isMeta']=d.get('isMeta')
        elif d.get('type')=='attachment':
            a=d.get('attachment',{})
            r['att']=a.get('type')
            r['attsize']=len(json.dumps(a))
            r['atttext']=json.dumps(a)[:600]
        elif d.get('type')=='system':
            r['content']=str(d.get('content'))[:1500]
            r['cm']=d.get('compactMetadata')
        recs[u]=r
L=sorted(recs.values(),key=lambda r:(r['ts'],r['n']))
json.dump(L,open('recs.json','w'))
print(len(L))
EOF
