        for b in r['blocks']:
            if b['k']=='tool_use': tu[b['id']]=(b['name'],b['input'])
def cls(nm,inp):
    if nm=='Read':
        for k in ('FACTS.md','POSITIONS.md','INDEX.md','protocol.md','README.md'):
            if k in inp: return k
        return 'Read other'
    if 'protocol.md' in inp: return 'protocol.md(bash)'
    if 'README.md' in inp and 'sed -n 1,80p' in inp: return 'README.md(bash)'
    if 'handover' in inp: return 'handover'
    if 'held-list' in inp: return 'boot note'
    return nm+' other'
def run(t0,t1,label,endts=None):
    sel=[r for r in L if t0<=r['ts']<t1]
    calls=[];seen=set()
    for r in sel:
        if r['type']=='assistant':
            if r['mid'] in seen:
                for c in calls:
                    if c['mid']==r['mid']: c['out']=max(c['out'],r['out'])
                continue
            seen.add(r['mid'])
            calls.append({'mid':r['mid'],'ts':r['ts'],'prompt':r['inp']+r['cr']+r['cc'],'out':r['out'],'items':[]})
        elif r['type']=='user' and calls:
            for b in r['blocks']:
                if b['k']=='tool_result':
                    nm,inp=tu.get(b['id'],('?',''))
                    calls[-1]['items'].append(('res',cls(nm,inp),b['bytes']))
        elif r['type']=='attachment' and calls:
            if r['att'] in('task_reminder','silent_turn_reminder','environment'):
                calls[-1]['items'].append(('rem',r['att'],r['attsize']))
    agg=collections.defaultdict(lambda:[0,0.0])
    for i in range(1,len(calls)):
        p=calls[i-1];c=calls[i]
        if endts and c['ts']>endts: break
        net=c['prompt']-p['prompt']-p['out']
        res=[x for x in p['items'] if x[0]=='res']
        rem=[x for x in p['items'] if x[0]=='rem']
        rb=sum(x[2] for x in res)
        remtok=sum(1300 if x[1]=='task_reminder' else (40 if x[1]=='silent_turn_reminder' else 120) for x in rem)+25
        agg['outputs of the assistant'][0]+=0
        agg['assistant output'][1]+=p['out']
        agg['reminders(inferred)'][1]+=remtok
        for x in res:
            agg[x[1]][0]+=x[2]
            agg[x[1]][1]+= (net-remtok)*x[2]/rb if rb else 0
    print('==',label,'first call prompt',calls[0]['prompt'], '(t=%s)'%calls[0]['ts'][11:19])
    tot=0
    for k,v in sorted(agg.items(),key=lambda kv:-kv[1][1]):
        print('   %-22s bytes=%7d  tokens=%7.0f  B/tok=%s'%(k,v[0],v[1],'%.2f'%(v[0]/v[1]) if v[1] and v[0] else '-'))
        tot+=v[1]
    # find end
    last=[c for c in calls if (not endts or c['ts']<=endts)][-1]
    print('   sum added',round(tot),' prompt at last call',last['prompt'],last['ts'][11:19])
